import math

def sharpe_se(sr_annual, n_years, periods=252):
    """Lo (2002): standard error of an annualised Sharpe from n_years of iid returns."""
    sr = sr_annual / math.sqrt(periods)        # per-period Sharpe
    T = n_years * periods                       # number of returns
    return math.sqrt((1 + sr ** 2 / 2) / T) * math.sqrt(periods)

